const DASHBOARD_WIDGETS = [
    { id:'wsPage', flag:'workspace', label:'分期與分數', x:20, y:100, w:1880, h:460, cx:20, cy:100, cw:1360, ch:460 },
    { id:'breastPage', flag:'breast', label:'乳癌藥物', x:20, y:580, w:940, h:460, cx:20, cy:580, cw:900, ch:360 },
    { id:'inpatientPage', flag:'inpatient', label:'住院化療', x:980, y:580, w:560, h:460, cx:940, cy:580, cw:520, ch:360 },
    { id:'icdPage', flag:'icd', label:'ICD 碼', x:1560, y:580, w:520, h:420, cx:20, cy:960, cw:520, ch:320 },
    { id:'surgeryPage', flag:'surgery', label:'手術醫材', x:20, y:1060, w:640, h:420, cx:560, cy:960, cw:560, ch:320 },
    { id:'trialsPage', flag:'trials', label:'臨床試驗', x:680, y:1060, w:640, h:420, cx:1140, cy:960, cw:520, ch:320 },
    { id:'calcPage', flag:'calc_gail', label:'乳癌計算機', x:1340, y:1060, w:740, h:420, cx:20, cy:1300, cw:900, ch:360, defaultVisible:false }
];
const DASHBOARD_VISIBLE_KEY = 'nhi_dashboard_widgets_v1';
const DASHBOARD_LAYOUT_KEY = 'nhi_dashboard_layout_v2';
const DASHBOARD_GRID = 20;
let _dashboardResizeObserver = null;
let _dashboardResizeSaveTimer = null;
let _dashboardDrag = null;

function snapDashboard(value){
    return Math.round(Number(value || 0) / DASHBOARD_GRID) * DASHBOARD_GRID;
}

function readDashboardJson(key, fallback){
    try {
        const saved = localStorage.getItem(key);
        return saved ? { ...fallback, ...JSON.parse(saved) } : { ...fallback };
    } catch(e){
        return { ...fallback };
    }
}
function getDashboardVisible(){
    const defaults = {};
    DASHBOARD_WIDGETS.forEach(w => defaults[w.id] = w.defaultVisible !== false);
    return readDashboardJson(DASHBOARD_VISIBLE_KEY, defaults);
}
function getDashboardLayout(){
    return readDashboardJson(DASHBOARD_LAYOUT_KEY, {});
}
function dashboardDefaultSize(widget){
    const compact = window.innerWidth <= 1450;
    const maxWidth = Math.max(320, window.innerWidth - 28);
    const w = compact ? (widget.cw || widget.w) : widget.w;
    const h = compact ? (widget.ch || widget.h) : widget.h;
    const x = compact ? (widget.cx ?? widget.x) : widget.x;
    const y = compact ? (widget.cy ?? widget.y) : widget.y;
    return { x: snapDashboard(x), y: snapDashboard(y), w: snapDashboard(Math.min(w, maxWidth)), h: snapDashboard(h) };
}
function isDashboardWidgetAvailable(widget){
    return !!FEATURE_FLAGS[widget.flag];
}
function renderDashboardControls(){
    const box = document.getElementById('dashboardControls');
    if(!box) return;
    const visible = getDashboardVisible();
    const items = DASHBOARD_WIDGETS
        .filter(isDashboardWidgetAvailable)
        .map(w => `<label class="dashboard-widget-toggle"><input type="checkbox" ${visible[w.id] !== false ? 'checked' : ''} onchange="setDashboardWidgetVisible('${w.id}',this.checked)"> ${w.label}</label>`)
        .join('');
    box.innerHTML = `<span class="dashboard-controls-title">Dashboard 模組</span>${items}<button type="button" onclick="resetDashboardLayout()">重設</button><span class="dashboard-controls-hint">拖曳標題列移動，右下角調整大小；會自動貼齊 20px 格線並記住</span>`;
}
function setDashboardWidgetVisible(id, checked){
    const visible = getDashboardVisible();
    visible[id] = !!checked;
    try { localStorage.setItem(DASHBOARD_VISIBLE_KEY, JSON.stringify(visible)); } catch(e){}
    showDesktopDashboard();
}
function resetDashboardLayout(){
    try {
        localStorage.removeItem(DASHBOARD_VISIBLE_KEY);
        localStorage.removeItem(DASHBOARD_LAYOUT_KEY);
    } catch(e){}
    showDesktopDashboard();
}
function applyDashboardWidgetLayout(){
    const visible = getDashboardVisible();
    const layout = getDashboardLayout();
    let maxRight = window.innerWidth;
    let maxBottom = 1500;
    DASHBOARD_WIDGETS.forEach((widget, index) => {
        const el = document.getElementById(widget.id);
        if(!el) return;
        const enabled = isDashboardWidgetAvailable(widget) && visible[widget.id] !== false;
        setPageActive(widget.id, enabled);
        el.classList.toggle('dashboard-widget', enabled);
        if(!enabled) return;
        const size = { ...dashboardDefaultSize(widget), ...(layout[widget.id] || {}) };
        const maxWidth = Math.max(320, window.innerWidth - 28);
        const width = Math.max(320, snapDashboard(Math.min(Number(size.w) || widget.w, maxWidth)));
        const height = Math.max(240, snapDashboard(Number(size.h) || widget.h));
        const x = Math.max(0, snapDashboard(Number(size.x) || 0));
        const y = Math.max(80, snapDashboard(Number(size.y) || 92));
        el.style.order = String(20 + index);
        el.style.setProperty('--dash-x', `${Math.round(x)}px`);
        el.style.setProperty('--dash-y', `${Math.round(y)}px`);
        el.style.setProperty('--dash-w', `${Math.round(width)}px`);
        el.style.setProperty('--dash-h', `${Math.round(height)}px`);
        maxRight = Math.max(maxRight, x + width + 24);
        maxBottom = Math.max(maxBottom, y + height + 24);
        prepareDashboardWidgetDrag(el);
    });
    updateDashboardCanvasSize(maxRight, maxBottom);
    observeDashboardWidgetSizes();
}
function updateDashboardCanvasSize(width, height){
    const container = document.querySelector('body.desktop-dashboard-mode .container');
    if(!container) return;
    container.style.setProperty('--dashboard-canvas-w', `${Math.round(width)}px`);
    container.style.setProperty('--dashboard-canvas-h', `${Math.round(height)}px`);
}
function saveDashboardWidgetLayout(id, patch){
    const layout = getDashboardLayout();
    layout[id] = { ...(layout[id] || {}), ...patch };
    try { localStorage.setItem(DASHBOARD_LAYOUT_KEY, JSON.stringify(layout)); } catch(e){}
}
function prepareDashboardWidgetDrag(el){
    if(el.dataset.dashboardDragReady === '1') return;
    const handle = el.querySelector('.page-topbar');
    if(!handle) return;
    el.dataset.dashboardDragReady = '1';
    handle.addEventListener('pointerdown', event => {
        if(!document.body.classList.contains('desktop-dashboard-mode')) return;
        if(event.button !== undefined && event.button !== 0) return;
        const container = document.querySelector('body.desktop-dashboard-mode .container');
        if(!container) return;
        const rect = el.getBoundingClientRect();
        const parentRect = container.getBoundingClientRect();
        _dashboardDrag = {
            id: el.id,
            el,
            container,
            startClientX: event.clientX,
            startClientY: event.clientY,
            startX: rect.left - parentRect.left + container.scrollLeft,
            startY: rect.top - parentRect.top + container.scrollTop
        };
        el.classList.add('dragging');
        handle.setPointerCapture?.(event.pointerId);
        event.preventDefault();
    });
    handle.addEventListener('pointermove', event => {
        if(!_dashboardDrag || _dashboardDrag.id !== el.id) return;
        const dx = event.clientX - _dashboardDrag.startClientX;
        const dy = event.clientY - _dashboardDrag.startClientY;
        const x = Math.max(0, snapDashboard(_dashboardDrag.startX + dx));
        const y = Math.max(80, snapDashboard(_dashboardDrag.startY + dy));
        el.style.setProperty('--dash-x', `${Math.round(x)}px`);
        el.style.setProperty('--dash-y', `${Math.round(y)}px`);
        updateDashboardCanvasFromWidgets();
    });
    const finishDrag = event => {
        if(!_dashboardDrag || _dashboardDrag.id !== el.id) return;
        const x = parseInt(el.style.getPropertyValue('--dash-x'), 10) || 0;
        const y = parseInt(el.style.getPropertyValue('--dash-y'), 10) || 92;
        saveDashboardWidgetLayout(el.id, { x, y });
        el.classList.remove('dragging');
        try { handle.releasePointerCapture?.(event.pointerId); } catch(e){}
        _dashboardDrag = null;
    };
    handle.addEventListener('pointerup', finishDrag);
    handle.addEventListener('pointercancel', finishDrag);
}
function updateDashboardCanvasFromWidgets(){
    let maxRight = window.innerWidth;
    let maxBottom = 1500;
    DASHBOARD_WIDGETS.forEach(widget => {
        const el = document.getElementById(widget.id);
        if(!el || !el.classList.contains('active')) return;
        const x = parseInt(el.style.getPropertyValue('--dash-x'), 10) || 0;
        const y = parseInt(el.style.getPropertyValue('--dash-y'), 10) || 0;
        const r = el.getBoundingClientRect();
        maxRight = Math.max(maxRight, x + r.width + 24);
        maxBottom = Math.max(maxBottom, y + r.height + 24);
    });
    updateDashboardCanvasSize(maxRight, maxBottom);
}
function observeDashboardWidgetSizes(){
    if(_dashboardResizeObserver) _dashboardResizeObserver.disconnect();
    if(typeof ResizeObserver === 'undefined') return;
    _dashboardResizeObserver = new ResizeObserver(entries => {
        if(!document.body.classList.contains('desktop-dashboard-mode')) return;
        const layout = getDashboardLayout();
        entries.forEach(entry => {
            const id = entry.target && entry.target.id;
            if(!id) return;
            const r = entry.target.getBoundingClientRect();
            const x = snapDashboard(parseInt(entry.target.style.getPropertyValue('--dash-x'), 10) || 0);
            const y = snapDashboard(parseInt(entry.target.style.getPropertyValue('--dash-y'), 10) || 92);
            const w = Math.max(320, snapDashboard(r.width));
            const h = Math.max(240, snapDashboard(r.height));
            entry.target.style.setProperty('--dash-x', `${x}px`);
            entry.target.style.setProperty('--dash-y', `${y}px`);
            entry.target.style.setProperty('--dash-w', `${w}px`);
            entry.target.style.setProperty('--dash-h', `${h}px`);
            layout[id] = { ...(layout[id] || {}), x, y, w, h };
        });
        updateDashboardCanvasFromWidgets();
        clearTimeout(_dashboardResizeSaveTimer);
        _dashboardResizeSaveTimer = setTimeout(() => {
            try { localStorage.setItem(DASHBOARD_LAYOUT_KEY, JSON.stringify(layout)); } catch(e){}
        }, 250);
    });
    DASHBOARD_WIDGETS.forEach(widget => {
        const el = document.getElementById(widget.id);
        if(el && el.classList.contains('active')) _dashboardResizeObserver.observe(el);
    });
}
function leaveDesktopDashboard(){
    document.body.classList.remove('desktop-dashboard-mode');
    if(_dashboardResizeObserver) _dashboardResizeObserver.disconnect();
    DASHBOARD_WIDGETS.forEach(widget => {
        const el = document.getElementById(widget.id);
        if(!el) return;
        el.classList.remove('dashboard-widget');
        el.classList.remove('dragging');
        el.style.removeProperty('--dash-x');
        el.style.removeProperty('--dash-y');
        el.style.removeProperty('--dash-w');
        el.style.removeProperty('--dash-h');
        el.style.removeProperty('order');
    });
}
