let _dashboardMode = true;
function loadDashboardMode(){
    try {
        const saved = localStorage.getItem('_dashboard_mode');
        _dashboardMode = saved == null ? true : saved === '1';
    } catch(e){}
}
function applyDashboardModeUI(){
    const ws = document.getElementById('wsPage');
    const btn = document.getElementById('wsModeToggle');
    if(!ws) return;
    ws.classList.add('dashboard-mode');
    if(btn){
        btn.classList.toggle('active', _dashboardMode);
        btn.innerHTML = _dashboardMode ? '\u{1F4CA} 自動計算' : '\u{1F4CB} 精簡填寫';
    }
}
function toggleDashboardMode(){
    _dashboardMode = !_dashboardMode;
    try { localStorage.setItem('_dashboard_mode', _dashboardMode?'1':'0'); } catch(e){}
    applyDashboardModeUI();
    refreshDashboardResults();
}

// Result-card builder
function _dashCard(opts){
    // opts: { id, title, desc, value, subtitle, extra, cls, badge, wide, missing, tab, titleAttr }
    const cls = ['ws-result-card'];
    if(opts.cls) cls.push(opts.cls);
    if(opts.wide) cls.push('wide');
    if(opts.missing) cls.push('empty');
    if(opts.tab && !opts.missing) cls.push('clickable');
    const badge = opts.badge ? `<span class="badge">${opts.badge}</span>` : '';
    const detailParts = [];
    if(opts.subtitle) detailParts.push(`<div>${opts.subtitle}</div>`);
    if(opts.extra) detailParts.push(`<div class="ws-result-extra">${opts.extra}</div>`);
    if(opts.tab) detailParts.push(`<a class="ws-result-open" href="#" onclick="event.stopPropagation();showCalc();switchCalcTab('${opts.tab}');return false;">開啟完整計算機</a>`);
    const detail = detailParts.length ? `<div class="ws-result-detail-panel">${detailParts.join('')}</div>` : '';
    const body = opts.missing
        ? `${opts.desc ? `<div class="ws-result-desc">${opts.desc}</div>` : ''}<div class="ws-result-empty">${opts.missing}</div>`
        : `${opts.desc ? `<div class="ws-result-desc">${opts.desc}</div>` : ''}<div class="ws-result-value">${opts.value ?? '—'}</div>${detail}`;
    const click = opts.tab && !opts.missing ? ` onclick="toggleRiskCard('${opts.id}')"` : '';
    const title = opts.titleAttr || (opts.tab && !opts.missing ? '點擊展開細節' : '');
    return `<div class="${cls.join(' ')}" id="dash-${opts.id}"${click}${title ? ` title="${title}"` : ''}>
        <div class="ws-result-title">${opts.title}${badge}</div>
        ${body}
    </div>`;
}

function toggleRiskCard(id){
    const card = document.getElementById('dash-' + id);
    if(!card || card.classList.contains('empty')) return;
    card.classList.toggle('expanded');
}

function _markerSign(v){
    const s = String(v ?? '').trim().toLowerCase();
    if(!s) return '';
    if(s === '+' || s.startsWith('+') || s.includes('陽') || s === 'pos' || s === 'positive') return '+';
    if(s === '-' || s.startsWith('-') || s.includes('陰') || s === 'neg' || s === 'negative') return '-';
    const n = Number(s.replace('%',''));
    if(!Number.isNaN(n)) return n >= 1 ? '+' : '-';
    return '';
}

function _markerPct(v){
    const s = String(v ?? '').trim().replace('%','');
    if(!s || s === '+' || s === '-') return null;
    const n = Number(s);
    return Number.isNaN(n) ? null : Math.max(0, Math.min(100, n));
}

function _markerHScore(v){
    const pct = _markerPct(v);
    if(pct !== null) return Math.round(pct * 3);
    return _markerSign(v) === '+' ? 200 : 0;
}

// ── Pure calc variants (no DOM access; pure functions of inputs) ──
function deriveWorkspaceICD(p){
    if(!p.quadrant || !p.side) return null;
    const ICD_BY_QUAD = {
        UO: {R:'C50.411', L:'C50.412', B:'C50.419'},
        UI: {R:'C50.211', L:'C50.212', B:'C50.219'},
        LO: {R:'C50.511', L:'C50.512', B:'C50.519'},
        LI: {R:'C50.311', L:'C50.312', B:'C50.319'},
        central: {R:'C50.111', L:'C50.112', B:'C50.119'},
        overlapping: {R:'C50.811', L:'C50.812', B:'C50.819'}
    };
    const QUAD_LABEL = {UO:'外上',UI:'內上',LO:'外下',LI:'內下',central:'乳頭/乳暈下',overlapping:'跨象限'};
    const SIDE_LABEL = {R:'右乳',L:'左乳',B:'雙側'};
    let code = null;
    if(p.T === 'Tis') code = 'D05.' + (p.quadrant==='central'?'81':p.quadrant==='overlapping'?'80':'82');
    else code = ICD_BY_QUAD[p.quadrant] ? ICD_BY_QUAD[p.quadrant][p.side] : null;
    if(!code) return null;
    return { code, subtitle: (SIDE_LABEL[p.side]||'') + ' ' + (QUAD_LABEL[p.quadrant]||'') };
}
function deriveWorkspaceSubtype(p){
    const er = _markerSign(p.er);
    if(!er || !p.her2) return null;
    if(p.her2==='+') return (er==='+') ? 'HR+/HER2+ (Luminal B-like)' : 'HR-/HER2+';
    if(p.her2==='low') return (er==='+') ? 'HR+/HER2-low' : 'TNBC (HER2-low)';
    if(er==='+'){
        const ki = +p.ki67;
        return (!isNaN(ki) && ki>=20) ? 'HR+/HER2- (Luminal B-like)' : 'HR+/HER2- (Luminal A-like)';
    }
    return 'TNBC (Triple Negative)';
}
function calcPEPIPure(tPts, nPts, erPts, ki67){
    if(![tPts,nPts,erPts,ki67].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    let kiPts;
    if(ki67<=2.7) kiPts=0;
    else if(ki67<=7.3) kiPts=1;
    else if(ki67<=19.7) kiPts=2;
    else if(ki67<=53.1) kiPts=3;
    else kiPts=4;
    const total = tPts+nPts+erPts+kiPts;
    let grp, cls, label, advice, rfs;
    if(total===0){ grp=1; cls='low'; label='Group 1（極佳）'; advice='Endocrine alone 即可，不需 adjuvant chemo。'; rfs='~95%'; }
    else if(total<=3){ grp=2; cls='med'; label='Group 2（中等）'; advice='個案討論加 chemo 的必要；視整體風險與病人偏好。'; rfs='~78%'; }
    else { grp=3; cls='high'; label='Group 3（高風險）'; advice='強烈建議 adjuvant chemo（在 endocrine 之外）。'; rfs='~58%'; }
    return { total, grp, cls, label, advice, rfs, parts:{ t:tPts, n:nPts, er:erPts, ki:kiPts } };
}
function calcCTS5Pure(N, T, G, A){
    if(![N,T,G,A].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    if(T<=0||A<=0) return null;
    const score = 0.438*N + 0.988*(0.093*T - 0.001*T*T) + 0.375*G + 0.017*A;
    const drr10 = (1 - Math.exp(-0.00223 * Math.exp(score))) * 100;
    let cls='low', label='低風險';
    if(score>=3.86){ cls='high'; label='高風險'; }
    else if(score>=3.13){ cls='med'; label='中度風險'; }
    return { score, drr10, cls, label };
}
function _logistic(x){
    return 1 / (1 + Math.exp(-x));
}
function _riskClass(pct, lowCut=10, highCut=30){
    if(pct < lowCut) return 'low';
    if(pct < highCut) return 'med';
    return 'high';
}
function getCTS5Exclusion(erSign, prSign, her2){
    if(erSign === '-' && prSign === '-') return 'CTS5 不適用於 ER−/PR−（HR−）乳癌。';
    if(her2 === '+') return 'CTS5 原模型不適用於 HER2+ 乳癌。';
    return null;
}
function calcNPIPure(size_cm, nodeStage, grade){
    if(!size_cm || !nodeStage || !grade) return null;
    const npi = 0.2*size_cm + nodeStage + grade;
    let group, surv5, cls;
    if(npi <= 2.4){ group='Excellent'; surv5='~95%'; cls='low'; }
    else if(npi <= 3.4){ group='Good'; surv5='~85%'; cls='low'; }
    else if(npi <= 4.4){ group='Moderate I'; surv5='~70%'; cls='med'; }
    else if(npi <= 5.4){ group='Moderate II'; surv5='~55%'; cls='med'; }
    else if(npi <= 6.4){ group='Poor'; surv5='~50%'; cls='high'; }
    else { group='Very Poor'; surv5='~30%'; cls='high'; }
    return { npi, group, surv5, cls };
}
function calcMageePure(ns, size_mm, erH, prH, her2cat, ki67){
    // ns = Nottingham 3-9, size_mm tumor mm, erH/prH H-score (0-300), her2cat 0/1/2, ki67 %
    if(![ns,size_mm,erH,prH,her2cat,ki67].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    const her2 = her2cat===2 ? 1 : 0;
    const m1 = 15.31385 + ns*1.4055 + erH*(-0.01924) + prH*(-0.02925) + her2*11.99435 + size_mm*0.0986;
    const m2 = 18.8042 + ns*2.34123 + erH*(-0.03749) + prH*(-0.03065) + her2*11.8378 + size_mm*0.13838 + ki67*0.0035;
    const erCat = erH>=200 ? 0 : (erH>=10 ? 1 : 2);
    const prCat = prH>=200 ? 0 : (prH>=10 ? 1 : 2);
    const her2Cat = her2cat>=2 ? 4 : (her2cat===1 ? 1.5 : 0);
    const nsCat = ns<=5 ? 0 : (ns<=7 ? 1 : 2);
    const kiCat = ki67<10 ? 0 : (ki67<20 ? 1 : 2);
    const sizeCat = size_mm<10 ? 0 : (size_mm<20 ? 1 : (size_mm<30 ? 2 : 3));
    const m3 = 13.424 + (erCat*1.4) + (prCat*1.6) + (her2Cat*5) + (nsCat*3) + (kiCat*1.6) + (sizeCat*0.5);
    const avg = (m1+m2+m3)/3;
    let cls='low', label='Low Risk';
    if(avg>=31){ cls='high'; label='High Risk'; }
    else if(avg>=18){ cls='med'; label='Intermediate Risk'; }
    return { m1, m2, m3, avg, cls, label };
}
function calcIHC4Pure(erH, prH, her2bin, ki67){
    if(![erH,prH,her2bin,ki67].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    const er10 = erH/30, pr10 = prH/30, ki67d = ki67/100;
    const ihc4 = 94.7 * (-0.100*er10 - 0.079*pr10 + 0.586*her2bin + 0.240*Math.log(1 + 10*ki67d));
    let group, cls;
    if(ihc4 < -25){ group='相對低 (近似)'; cls='low'; }
    else if(ihc4 < 0){ group='較低 (近似)'; cls='low'; }
    else if(ihc4 < 25){ group='中等 (近似)'; cls='med'; }
    else { group='相對高 (近似)'; cls='high'; }
    return { ihc4, group, cls };
}
function calcHscorePure(p0, p1, p2, p3){
    if(![p0,p1,p2,p3].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    const total = p0+p1+p2+p3;
    const h = 1*p1 + 2*p2 + 3*p3;
    let group, cls;
    if(h === 0){ group='陰性'; cls='low'; }
    else if(h < 100){ group='Low'; cls='low'; }
    else if(h < 200){ group='Intermediate'; cls='med'; }
    else { group='High'; cls='high'; }
    return { h, total, group, cls };
}
function calcRCBPure(d1, d2, finvPct, ln, dmet){
    if(![d1,d2,finvPct,ln,dmet].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    const finv = finvPct/100;
    const dprim = Math.sqrt(Math.max(d1,0) * Math.max(d2,0));
    let primComp = 0;
    if(dprim > 0 && finv > 0) primComp = 1.4 * Math.pow(finv * dprim, 0.17);
    let nodalComp = 0;
    if(ln > 0 && dmet > 0) nodalComp = Math.pow(4 * (1 - Math.pow(0.75, ln)) * dmet, 0.17);
    const rcb = primComp + nodalComp;
    let cls, klass, surv;
    if(rcb === 0){ klass='RCB-0 (pCR)'; cls='low'; surv='10y DFS ~95%'; }
    else if(rcb <= 1.36){ klass='RCB-I (Minimal)'; cls='low'; surv='10y DFS ~75%'; }
    else if(rcb <= 3.28){ klass='RCB-II (Moderate)'; cls='med'; surv='10y DFS ~55%'; }
    else { klass='RCB-III (Extensive)'; cls='high'; surv='10y DFS ~30%'; }
    return { rcb, cls, klass, surv, dprim, primComp, nodalComp };
}
function calcGailPure(age, rrMen, rrBirth, rrRel, biopsy, atypia, race){
    if(!age || age < 35 || age > 85) return null;
    let rrBio = 1.0;
    if(biopsy === 1) rrBio = atypia ? 1.93 : 1.27;
    else if(biopsy === 2) rrBio = atypia ? 2.45 : 1.62;
    const totalRR = rrMen * rrBirth * rrRel * rrBio;
    const raceAdj = { white: 1.0, aa: 0.95, asian: 0.5, hispanic: 0.7 };
    const raceFactor = raceAdj[race] || 1.0;
    const ageBands = [
        [35, 0.3], [40, 0.6], [45, 1.0], [50, 1.4], [55, 1.7],
        [60, 1.9], [65, 2.0], [70, 2.0], [75, 1.9], [80, 1.7]
    ];
    let baseline5y = 0.3;
    for(const [a, r] of ageBands){ if(age >= a) baseline5y = r; }
    const risk5y = baseline5y * totalRR * raceFactor;
    const risk5yCapped = Math.min(risk5y, 50);
    const lifetimeFactor = age < 50 ? 8 : age < 60 ? 6 : age < 70 ? 4 : 2.5;
    const lifetimeRisk = Math.min(baseline5y * totalRR * raceFactor * lifetimeFactor, 80);
    let cls, advice;
    if(risk5yCapped < 1.67){ cls='low'; advice='低風險（5 年 &lt;1.67%）。一般年度篩檢即可。'; }
    else if(risk5yCapped < 3){ cls='med'; advice='中度風險。可考慮加強篩檢頻率。'; }
    else { cls='high'; advice='<strong>高風險（5 年 ≥3%）</strong>。考慮 chemoprevention（Tamoxifen / AI / Raloxifene）；建議轉介遺傳諮詢。'; }
    return { risk5y: risk5yCapped, lifetimeRisk, totalRR, rrBio, raceFactor, cls, advice };
}
function calcQiuAlnPure(td, cortex, hilumAbsent, grade, sizeCm, erScore){
    if(![td,cortex,hilumAbsent,grade,sizeCm,erScore].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    const d1 = grade === 2 ? 1 : 0;
    const d2 = grade === 3 ? 1 : 0;
    const logit = 0.063*td + 0.277*cortex + 1.420*hilumAbsent + 1.502*d1 + 2.090*d2 + 0.305*sizeCm + 0.379*erScore - 5.710;
    const risk = _logistic(logit) * 100;
    return { logit, risk, cls:_riskClass(risk, 13.8, 50) };
}
function calcNonSlnPure(sizeCm, multifocal, lvi, positiveSln, negativeSln){
    if(![sizeCm,multifocal,lvi,positiveSln,negativeSln].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    const logit = 0.267*sizeCm + 1.443*multifocal + 1.078*lvi + 0.471*positiveSln - 0.618*negativeSln - 2.541;
    const risk = _logistic(logit) * 100;
    return { logit, risk, cls:_riskClass(risk, 10, 30) };
}
function calcLevel2AlnPure(posLevel1, tumorT, ki67High, grade){
    if(![posLevel1,tumorT,ki67High,grade].every(v=>typeof v==='number'&&!isNaN(v))) return null;
    const a = Math.min(Math.max(Math.round(posLevel1), 1), 5);
    const d1 = grade === 2 ? 1 : 0;
    const d2 = grade === 3 ? 1 : 0;
    const logit = 0.683*a + 0.552*tumorT + 0.728*ki67High + 0.922*d1 + 1.506*d2 - 5.314;
    const risk = _logistic(logit) * 100;
    return { logit, risk, cls:_riskClass(risk, 10, 30) };
}
function calcPredictPure(p){
    // p: {age, size_mm, nodes_pos, grade, er, her2, ki67Pct, mode}
    const age = +p.age, size = +p.size_mm, nodes = +p.nodes_pos, grade = +p.grade;
    if(!age||!size||isNaN(nodes)||!grade||age<25||age>85||size<1) return null;
    if(p.er!=='+' && p.er!=='-') return null;
    const isERpos = p.er === '+';
    const her2tok = p.her2==='+' ? 'pos' : ((p.her2==='-'||p.her2==='low') ? 'neg' : 'unk');
    const ki67tok = (typeof p.ki67Pct==='number'&&!isNaN(p.ki67Pct)) ? (p.ki67Pct>=10?'pos':'neg') : 'unk';
    const mode = p.mode || 'symp';
    const pi = isERpos
        ? _predictPI_ERpos(age, size, nodes, grade, mode, her2tok, ki67tok)
        : _predictPI_ERneg(age, size, nodes, grade, mode, her2tok);
    const mi = _predictMI(age);
    const years = [5,10,15];
    const cumBC0 = [], cumOC0 = [];
    for(let t=1; t<=15; t++){
        cumBC0.push(_predictBaseCumBC(t, isERpos));
        cumOC0.push(_predictBaseCumOC(t));
    }
    const annBC0 = cumBC0.map((v,i)=> i===0 ? v : v - cumBC0[i-1]);
    const annOC0 = cumOC0.map((v,i)=> i===0 ? v : v - cumOC0[i-1]);
    const annBC = annBC0.map(v => v * Math.exp(pi));
    const annOC = annOC0.map(v => v * Math.exp(mi));
    let acc=0; const cumBC = annBC.map(v=>(acc+=v));
    acc=0; const cumOC = annOC.map(v=>(acc+=v));
    const sBC = cumBC.map(c => Math.exp(-c));
    const sOC = cumOC.map(c => Math.exp(-c));
    const sAll = sBC.map((b,i)=> b*sOC[i]);
    return { pi, surv: years.map(y=>sAll[y-1]*100), years };
}

function _ajccCleanToken(v, kind){
    let s = String(v ?? '').trim();
    if(!s) return '';
    if(kind === 'T') s = s.replace(/^[cp]T/i, 'T');
    if(kind === 'N') s = s.replace(/^[cp]N/i, 'N');
    if(kind === 'M') s = s.replace(/^[cp]M/i, 'M');
    return s;
}
function _gradeNumber(v){
    const s = String(v ?? '').trim();
    if(!s) return null;
    const m = s.match(/[123]/);
    return m ? Number(m[0]) : null;
}
function _her2StageSign(v){
    const s = String(v ?? '').trim().toLowerCase();
    if(!s) return '';
    if(s === '+' || s.startsWith('+') || s.includes('positive') || s.includes('pos') || s.includes('陽')) return '+';
    if(s === '-' || s.startsWith('-') || s === 'low' || s.includes('negative') || s.includes('neg') || s.includes('陰')) return '-';
    return '';
}
function calcWorkspaceAjccPrognostic(p){
    const t = _ajccCleanToken(p.T, 'T');
    const n = _ajccCleanToken(p.N, 'N');
    const m = _ajccCleanToken(p.M, 'M');
    const grade = _gradeNumber(p.grade);
    const er = _markerSign(p.er);
    const pr = _markerSign(p.pr);
    const her2 = _her2StageSign(p.her2);
    const missing = [];
    if(!t || !n || !m) missing.push('TNM');
    if(!grade) missing.push('Grade');
    if(!er) missing.push('ER');
    if(!pr) missing.push('PR');
    if(!her2) missing.push('HER2');
    if(missing.length) return { stage:null, missing, t, n, m, grade, er, pr, her2 };
    let stage = null;
    try { stage = _ajcc9Lookup(t, n, m, grade, er, pr, her2); } catch(e){}
    return { stage, missing:[], t, n, m, grade, er, pr, her2 };
}

function renderWorkspaceStageSummary(p){
    const el = document.getElementById('wsStageResults');
    if(!el) return;
    const st = getWorkspaceStage(p);
    if(st.T && st.N && st.M) p = { ...p, T: st.T, N: st.N, M: st.M, stageKind: st.kind };
    if(!p.T || !p.N || !p.M){
        el.innerHTML = '<div class="ws-empty">請先填入 T / N / M，完成後會自動顯示 AJCC 第八版解剖期別。</div>';
        return;
    }
    let anat = '—';
    try { anat = _ajccAnatomic(p.T, p.N, p.M) || '—'; } catch(e){}
    const stageClass = anat === 'IV' ? 'bad' : (['IIA','IIB','IIIA','IIIB','IIIC'].includes(anat) ? 'warn' : 'good');
    const progCalc = calcWorkspaceAjccPrognostic(p);
    const prog = progCalc.stage;
    const progText = prog
        ? `病理/臨床預後期別：第 ${prog} 期`
        : (progCalc.missing.length
            ? `尚缺：${progCalc.missing.join(' / ')}`
            : `AJCC v8 查表未命中：${progCalc.t}/${progCalc.n}/${progCalc.m} G${progCalc.grade} ER${progCalc.er} PR${progCalc.pr} HER2${progCalc.her2}`);
    const subtype = deriveWorkspaceSubtype(p);
    const subtypeText = subtype ? `分子亞型：${subtype}` : '';
    el.innerHTML = `
      <div class="ws-stage-card primary ${stageClass}">
        <div class="ws-stage-label">AJCC v8 解剖期別</div>
        <div class="ws-stage-inline">
          <span class="ws-stage-value">${anat==='—' ? '—' : '第 ' + anat + ' 期'}</span>
          <span class="ws-stage-sub">${p.stageKind || 'TNM'}: ${p.T} / ${p.N} / ${p.M}</span>
        </div>
      </div>
      <div class="ws-stage-card">
        <div class="ws-stage-label">AJCC v8 預後期別</div>
        <div class="ws-stage-inline">
          <span class="ws-stage-value">${prog ? '第 ' + prog + ' 期' : '—'}</span>
          <span class="ws-stage-sub">${progText}${subtypeText ? '　' + subtypeText : ''}</span>
        </div>
      </div>`;
}

// ── Renderer: read _patient, render all panels into #wsResults ──
function refreshDashboardResults(){
    const el = document.getElementById('wsResults');
    if(!el) return;
    let p = _patient;
    const st = getWorkspaceStage(p);
    if(st.T && st.N && st.M) p = { ...p, T: st.T, N: st.N, M: st.M, stageKind: st.kind };
    renderWorkspaceStageSummary(p);
    const cards = [];
    const erSign = _markerSign(p.er);
    const prSign = _markerSign(p.pr);
    const gradeNum = _gradeNumber(p.grade);

    // 1) AJCC stage (anatomic + v8 prognostic)
    if(p.T && p.N && p.M){
        let anat = '—';
        try { anat = _ajccAnatomic(p.T,p.N,p.M) || '—'; } catch(e){}
        const progCalc = calcWorkspaceAjccPrognostic(p);
        const prog = progCalc.stage || '';
        const eligible = ['IIA','IIB','IIIA','IIIB','IIIC','IV'].includes(anat);
        cards.push(_dashCard({
            id:'ajcc',
            title:'AJCC 期別',
            value: anat==='—' ? '—' : ('第 '+anat+' 期'),
            subtitle: prog ? ('v8 預後期別: '+prog) : (progCalc.missing.length ? ('缺 '+progCalc.missing.join('/')) : 'v8 預後期別查表未命中'),
            cls: eligible ? 'high' : (anat==='—'?'':'low'),
            titleAttr:'依 Workspace TNM / biomarker 即時計算'
        }));
    } else {
        cards.push(_dashCard({ id:'ajcc', title:'AJCC 期別', missing:'需 T / N / M' }));
    }

    // 2) CTS5 (Dowsett 2018: tumor size in mm)
    const cts5Exclusion = getCTS5Exclusion(erSign, prSign, p.her2);
    if(cts5Exclusion){
        cards.push(_dashCard({
            id:'cts5', title:'CTS5', desc:'內分泌治療後晚期遠端復發風險',
            missing: cts5Exclusion,
            tab:'cts5'
        }));
    } else if(p.nodes_pos!=='' && p.size && gradeNum && p.age){
        const r = calcCTS5Pure(+p.nodes_pos, +p.size, gradeNum, +p.age);
        if(r) cards.push(_dashCard({
            id:'cts5', title:'CTS5', desc:'內分泌治療 5 年後，估算第 5–10 年遠端復發風險',
            value: r.score.toFixed(2),
            subtitle: r.label + ' · 10y DRR ≈ '+r.drr10.toFixed(1)+'%',
            cls: r.cls,
            tab:'cts5'
        }));
        else cards.push(_dashCard({ id:'cts5', title:'CTS5', desc:'內分泌治療後晚期遠端復發風險', missing:'資料不完整' }));
    } else {
        cards.push(_dashCard({ id:'cts5', title:'CTS5', desc:'內分泌治療後晚期遠端復發風險', missing:'需 N+ / size / Grade / age' }));
    }

    // 2b) PEPI (post-neoadjuvant endocrine; Workspace uses current pathology as proxy)
    if(erSign && erSign !== '+'){
        cards.push(_dashCard({
            id:'pepi', title:'PEPI', desc:'術前內分泌治療後，用病理反應估算復發風險',
            missing:'主要適用 ER+ 且完成術前內分泌治療後',
            tab:'pepi'
        }));
    } else if(erSign==='+' && p.size && p.nodes_pos!=='' && p.ki67){
        const tPts = (+p.size > 50 || /^T[34]/.test(p.T||'')) ? 3 : 0;
        const nPts = (+p.nodes_pos > 0 || (p.N && p.N !== 'N0')) ? 3 : 0;
        const r = calcPEPIPure(tPts, nPts, 0, +p.ki67);
        if(r) cards.push(_dashCard({
            id:'pepi', title:'PEPI', desc:'術前內分泌治療後，用病理反應估算復發風險',
            value: r.total,
            subtitle: r.label + ' · 5y RFS '+r.rfs,
            extra:'以目前 Workspace 病理作近似：pT '+r.parts.t+' / pN '+r.parts.n+' / ER '+r.parts.er+' / Ki67 '+r.parts.ki,
            cls: r.cls,
            badge:'近似',
            tab:'pepi'
        }));
    } else {
        cards.push(_dashCard({ id:'pepi', title:'PEPI', desc:'術前內分泌治療後病理風險分數', missing:'需 ER+ / size / N+ / Ki67', tab:'pepi' }));
    }

    // 3) PREDICT
    if(p.age && p.size && p.nodes_pos!=='' && gradeNum && erSign && p.her2){
        const r = calcPredictPure({
            age:+p.age, size_mm:+p.size, nodes_pos:+p.nodes_pos, grade: gradeNum,
            er: erSign, her2: p.her2, ki67Pct: p.ki67?+p.ki67:NaN, mode: p.predict_mode || 'symp'
        });
        if(r){
            const [s5,s10,s15] = r.surv;
            cards.push(_dashCard({
                id:'predict', title:'PREDICT v2.3', desc:'術後整體存活率與輔助治療獲益估算',
                value: '5y OS '+s5.toFixed(1)+'%',
                subtitle: 'Overall survival · 5y '+s5.toFixed(1)+'%',
                extra:'PI = '+r.pi.toFixed(2),
                cls: s5>=90?'low':(s5>=80?'med':'high'),
                tab:'predict'
            }));
        } else {
            cards.push(_dashCard({ id:'predict', title:'PREDICT v2.3', desc:'術後整體存活率估算', missing:'資料超出模型範圍 (age 25-85, size≥1mm)' }));
        }
    } else {
        cards.push(_dashCard({ id:'predict', title:'PREDICT v2.3', desc:'術後整體存活率估算', missing:'需 age/size/N+/Grade/ER/HER2' }));
    }

    // 4) NPI
    if(p.size && p.nodes_pos!=='' && gradeNum){
        const npos = +p.nodes_pos;
        const nodeStage = npos===0?1:(npos<=3?2:3);
        const r = calcNPIPure(+p.size/10, nodeStage, gradeNum);
        if(r) cards.push(_dashCard({
            id:'npi', title:'NPI', desc:'Nottingham Prognostic Index，依大小、淋巴結、Grade 分層',
            value: r.npi.toFixed(2),
            subtitle: r.group + ' · 5y '+r.surv5,
            cls: r.cls,
            tab:'npi'
        }));
    } else {
        cards.push(_dashCard({ id:'npi', title:'NPI', desc:'依大小、淋巴結、Grade 估算預後分層', missing:'需 size / N+ / Grade' }));
    }

    // 5) Magee (估算 Oncotype RS)
    if(p.size && gradeNum && erSign && prSign && p.her2 && p.ki67){
        // Map workspace fields to magee inputs.
        const erH = _markerHScore(p.er);
        const prH = _markerHScore(p.pr);
        const ns = gradeNum * 2 + 1; // 1->3, 2->5, 3->7 rough Nottingham proxy
        const her2cat = p.her2==='+' ? 2 : (p.her2==='low' ? 1 : 0);
        const r = calcMageePure(ns, +p.size, erH, prH, her2cat, +p.ki67);
        if(r){
            cards.push(_dashCard({
                id:'magee', title:'Magee (估算 RS)', desc:'以病理與 IHC 近似估算 Oncotype DX RS',
                value: r.avg.toFixed(1),
                subtitle: r.label,
                extra: 'Eq.1='+r.m1.toFixed(1)+' · Eq.2='+r.m2.toFixed(1)+' · Eq.3='+r.m3.toFixed(1),
                cls: r.cls,
                badge: '近似',
                tab:'magee'
            }));
        }
    } else {
        cards.push(_dashCard({ id:'magee', title:'Magee (估算 RS)', desc:'以病理與 IHC 近似估算 Oncotype DX RS', missing:'需 size/Grade/ER/PR/HER2/Ki67' }));
    }

    // 6) IHC4
    if(erSign && prSign && p.her2 && p.ki67){
        const erH = _markerHScore(p.er);
        const prH = _markerHScore(p.pr);
        const her2bin = p.her2==='+' ? 1 : 0;
        const r = calcIHC4Pure(erH, prH, her2bin, +p.ki67);
        if(r) cards.push(_dashCard({
            id:'ihc4', title:'IHC4', desc:'用 ER、PR、HER2、Ki-67 估算 IHC 復發風險',
            value: r.ihc4.toFixed(1),
            subtitle: r.group,
            cls: r.cls,
            badge: '近似',
            tab:'ihc4'
        }));
    } else {
        cards.push(_dashCard({ id:'ihc4', title:'IHC4', desc:'IHC 乳癌復發風險分數', missing:'需 ER/PR/HER2/Ki67' }));
    }

    // H-score is intentionally omitted from the staging workspace.
    if(false && p.h_p0!=='' && p.h_p1!=='' && p.h_p2!=='' && p.h_p3!==''){
        const r = calcHscorePure(+p.h_p0, +p.h_p1, +p.h_p2, +p.h_p3);
        if(r) cards.push(_dashCard({
            id:'hscore',
            title:'H-score',
            desc:'IHC 染色強度百分比換算的受體表現分數',
            value: r.h,
            subtitle: r.group + (r.total !== 100 ? ' · 百分比合計 ' + r.total + '%' : ''),
            cls: r.cls,
            tab:'hscore'
        }));
    } else if(false) {
        cards.push(_dashCard({
            id:'hscore',
            title:'H-score',
            desc:'IHC 染色強度百分比換算的受體表現分數',
            missing:'需 0/1+/2+/3+ 染色百分比',
            tab:'hscore'
        }));
    }

    // 6c) RCB
    if(p.rcb_d1!=='' && p.rcb_d2!=='' && p.rcb_finv!=='' && p.rcb_ln!=='' && p.rcb_dmet!==''){
        const r = calcRCBPure(+p.rcb_d1, +p.rcb_d2, +p.rcb_finv, +p.rcb_ln, +p.rcb_dmet);
        if(r) cards.push(_dashCard({
            id:'rcb',
            title:'RCB',
            desc:'術前治療後殘餘癌負荷，用於評估病理反應',
            value: r.rcb.toFixed(2),
            subtitle: r.klass + ' · ' + r.surv,
            extra: 'dprim=' + r.dprim.toFixed(1) + ' mm · primary=' + r.primComp.toFixed(2) + ' · nodal=' + r.nodalComp.toFixed(2),
            cls: r.cls,
            tab:'rcb'
        }));
    } else if(false) {
        cards.push(_dashCard({
            id:'rcb',
            title:'RCB',
            desc:'術前治療後殘餘癌負荷，用於評估病理反應',
            missing:'需 tumor bed / invasive % / LN metastasis size',
            tab:'rcb'
        }));
    }

    // 6d) Gail moved to landing page; do not show it in patient staging workspace.
    if(false){
    if(p.age){
        const r = calcGailPure(+p.age, +p.gail_menarche, +p.gail_birth, +p.gail_relatives, +p.gail_biopsy, +p.gail_atypia, p.gail_race);
        if(r) cards.push(_dashCard({
            id:'gail',
            title:'Gail Model',
            desc:'乳癌發生風險估算，不是已診斷乳癌預後分數',
            value: r.risk5y.toFixed(2)+'%',
            subtitle:'5 年風險 · 終身粗估 '+r.lifetimeRisk.toFixed(1)+'%',
            extra:'以亞洲族群與低風險預設值估算；正式決策請用 NCI BCRAT。',
            cls:r.cls,
            badge:'簡化',
            tab:'gail'
        }));
        else cards.push(_dashCard({ id:'gail', title:'Gail Model', desc:'乳癌發生風險估算', missing:'年齡需 35–85 歲', tab:'gail' }));
    } else {
        cards.push(_dashCard({ id:'gail', title:'Gail Model', desc:'乳癌發生風險估算', missing:'需 age', tab:'gail' }));
    }

    }

    // 7) Molecular subtype
    let subtype = deriveWorkspaceSubtype(p);
    cards.push(_dashCard({
        id:'subtype', title:'分子亞型',
        value: subtype || '—',
        missing: subtype ? null : '需 ER / HER2'
    }));

    // 8) ICD-10
    const icdInfo = deriveWorkspaceICD(p);
    cards.push(_dashCard({
        id:'icd', title:'ICD-10-CM',
        value: icdInfo ? icdInfo.code : null,
        subtitle: icdInfo ? icdInfo.subtitle : '',
        missing: icdInfo ? null : '需側別 + 象限'
    }));

    // 10) BSA / CrCl combined card
    const h = +p.height, w = +p.weight, ageN=+p.age, scrN=+p.scr;
    const bsa = (h>0&&w>0) ? Math.sqrt(h*w/3600) : null;
    const crcl = (ageN>0&&w>0&&scrN>0) ? ((140-ageN)*w/(72*scrN))*(p.sex==='F'?0.85:1) : null;
    if(bsa || crcl){
        cards.push(_dashCard({
            id:'bsa-crcl', title:'BSA / CrCl',
            value: bsa ? (bsa.toFixed(2)+' m²') : '—',
            subtitle: crcl ? ('CrCl '+crcl.toFixed(0)+' mL/min') : 'CrCl 需 age/weight/Cr'
        }));
    } else {
        cards.push(_dashCard({ id:'bsa-crcl', title:'BSA / CrCl', missing:'需 身高/體重 (與 age/Cr)' }));
    }

    const scoreCards = cards
        .filter(html => !['dash-ajcc','dash-subtype','dash-icd','dash-catas','dash-bsa-crcl','dash-hscore'].some(id => html.includes(`id="${id}"`)))
        .sort((a,b) => (a.includes('ws-result-card empty') ? 1 : 0) - (b.includes('ws-result-card empty') ? 1 : 0));
    const osCards = scoreCards.filter(html => ['dash-predict','dash-npi'].some(id => html.includes(`id="${id}"`)));
    const recurrenceCards = scoreCards.filter(html => !['dash-predict','dash-npi'].some(id => html.includes(`id="${id}"`)));
    const section = (title, subtitle, items) => `
      <div class="ws-score-section">
        <div class="ws-score-section-title">${title}<span>${subtitle}</span></div>
        <div class="ws-score-grid">${items.join('')}</div>
      </div>`;
    el.innerHTML = [
        section('1. OS overall survival', 'overall survival / prognostic survival', osCards),
        section('2. Recurrence risk', 'recurrence risk / residual disease risk', recurrenceCards)
    ].join('');
}

function exportPatientWorkspace(){
    const data = JSON.stringify(_patient, null, 2);
    const blob = new Blob([data], {type:'application/json'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `patient_workspace_${(_patient.mrn||'unnamed')}_${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 1000);
}
function importPatientWorkspace(){
    const input = document.createElement('input');
    input.type = 'file'; input.accept = 'application/json,.json';
    input.onchange = e => {
        const f = e.target.files[0]; if(!f) return;
        const reader = new FileReader();
        reader.onload = ev => {
            try {
                const obj = JSON.parse(ev.target.result);
                _patient = { ...PATIENT_DEFAULTS, ...obj };
                migrateWorkspaceSurgeryFields();
                savePatient();
                initWorkspace();
                alert('已載入 workspace');
            } catch(err){ alert('JSON 格式錯誤：'+err.message); }
        };
        reader.readAsText(f);
    };
    input.click();
}
