// ── Patient Journey Explanation (Beta / 開發中) ──
function _journeyEsc(s){
    return String(s==null?'':s).replace(/[<>&"]/g, c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c]));
}
function _journeyItem(icon, text){
    return `<div class="journey-item"><span class="icon">${icon}</span><span>${text}</span></div>`;
}
function _journeyFact(label, value, note){
    return `<div class="journey-fact">
        <div class="journey-fact-label">${label}</div>
        <div class="journey-fact-value">${value}</div>
        ${note ? `<div class="journey-fact-note">${note}</div>` : ''}
    </div>`;
}
function _journeyMarker(label, value){
    let dot = 'warn';
    if(value==='+' || value==='陽性' || value==='brca1' || value==='brca2') dot = 'pos';
    if(value==='-' || value==='陰性' || value==='wt') dot = 'neg';
    const shown = value ? _journeyEsc(value) : '未填';
    return `<span class="journey-marker"><span class="journey-dot ${dot}"></span>${label}: ${shown}</span>`;
}
function _journeyStageInfo(p, anat){
    if(!p.T && !p.N && !p.M) return { idx:0, label:'資料整理中', main:'先把病理與分期資料集中到同一頁', sub:'這個模組會把 Workspace 內容整理成面對病人說明時的精華摘要。' };
    if(p.M === 'M1' || anat === 'IV') return { idx:4, label:'轉移性治療', main:'目前重點是治療目標、用藥條件與費用資訊', sub:'可先整理生物標記、前線治療與健保條件，方便門診說明。' };
    if(p.phase === 'neoadjuvant') return { idx:1, label:'術前治療', main:'目前重點是術前治療目標與後續手術規劃', sub:'需要把腫瘤特性、藥物選項、治療反應評估與費用討論串在一起。' };
    if(p.phase === 'adjuvant') return { idx:3, label:'術後輔助治療', main:'目前重點是降低復發風險與說明輔助治療選項', sub:'分期與生物標記可協助說明為什麼需要討論不同治療。' };
    if(p.phase === 'advanced') return { idx:1, label:'局部晚期規劃', main:'目前重點是治療順序與跨科溝通', sub:'可先確認分期、receptor 狀態、是否需要術前治療與影像追蹤。' };
    return { idx:1, label:'診斷與分期說明', main:'目前重點是讓病人理解分期與腫瘤特性', sub:'接下來通常會確認治療階段、是否需要補檢驗，以及費用/健保相關問題。' };
}
function renderPatientJourney(){
    const p = _patient || {};
    const hero = document.getElementById('journeyHero');
    const facts = document.getElementById('journeyFacts');
    const markers = document.getElementById('journeyMarkers');
    const missing = document.getElementById('journeyMissing');
    const questions = document.getElementById('journeyQuestions');
    if(!hero || !facts || !markers || !missing || !questions) return;

    let anat = '—';
    if(p.T && p.N && p.M){
        try { anat = _ajccAnatomic(p.T, p.N, p.M) || '—'; } catch(e){ anat = '—'; }
    }
    const subtype = deriveWorkspaceSubtype(p) || '—';
    const icdInfo = deriveWorkspaceICD(p);
    const stageInfo = _journeyStageInfo(p, anat);
    const stageText = anat==='—' ? '尚未完成' : `第 ${anat} 期`;
    const phaseLabel = {neoadjuvant:'術前治療',adjuvant:'術後輔助治療',advanced:'局部晚期',metastatic:'轉移性 first-line',metastatic_2L:'轉移性後線'}[p.phase] || '尚未設定';
    const steps = ['診斷分期','術前治療','手術','術後輔助','轉移/追蹤'];

    hero.innerHTML = `
      <div class="journey-stage">${stageInfo.label}</div>
      <div class="journey-main">${stageInfo.main}</div>
      <div class="journey-sub">${stageInfo.sub}</div>
      <div class="journey-steps">
        ${steps.map((s,i)=>`<div class="journey-step ${i<stageInfo.idx?'done':i===stageInfo.idx?'active':''}"><span class="num">${i+1}</span>${s}</div>`).join('')}
      </div>`;

    const nhiReady = p.T && p.N && p.M && p.er && p.her2;
    const catas = ['IIA','IIB','IIIA','IIIB','IIIC','IV'].includes(anat) ? '可協助準備申請資料' : (anat==='—' ? '目前資料不足' : '需依正式條件確認');
    facts.innerHTML = [
        _journeyFact('分期', stageText, p.T&&p.N&&p.M ? `${_journeyEsc(p.T)} / ${_journeyEsc(p.N)} / ${_journeyEsc(p.M)}` : '需 T/N/M'),
        _journeyFact('治療階段', _journeyEsc(phaseLabel), '用來對齊費用與健保條件'),
        _journeyFact('腫瘤亞型', _journeyEsc(subtype), subtype==='—' ? '需 ER/HER2' : '用白話解釋治療分類'),
        _journeyFact('ICD / 重大傷病', _journeyEsc(icdInfo ? icdInfo.code : '待確認'), catas),
        _journeyFact('健保條件對照', nhiReady ? '可初步對照' : '需補資料', nhiReady ? '仍以院內與健保署審核為準' : '通常需分期與 receptor'),
        _journeyFact('費用說明', '聚焦自費差異', '適合搭配藥物費用與手術自費清單')
    ].join('');

    markers.innerHTML = [
        _journeyMarker('ER', p.er),
        _journeyMarker('PR', p.pr),
        _journeyMarker('HER2', p.her2),
        _journeyMarker('Ki-67', p.ki67 ? `${p.ki67}%` : ''),
        _journeyMarker('BRCA', p.brca),
        _journeyMarker('PD-L1', p.pdl1)
    ].join('');

    const gaps = [];
    if(!p.T || !p.N || !p.M) gaps.push('補齊 T / N / M，才能清楚說明分期、重大傷病與部分健保條件。');
    if(!p.er || !p.pr || !p.her2) gaps.push('補齊 ER / PR / HER2，這是乳癌治療分類與藥物條件的核心資料。');
    if(!p.size || p.nodes_pos==='') gaps.push('補上腫瘤大小與陽性淋巴結數，方便用圖像化方式說明風險與模型。');
    if(!p.brca && (p.her2==='-' || p.her2==='low')) gaps.push('若後續討論特定標靶或遺傳風險，可確認是否需要 BRCA 資料。');
    if(!gaps.length) gaps.push('目前核心說明資料大致齊全，可進一步搭配藥物費用與整合摘要列印。');
    missing.innerHTML = gaps.map(x=>_journeyItem('□', _journeyEsc(x))).join('');

    const q = [];
    q.push('今天最需要讓病人理解的是：目前分期、受體狀態，以及下一步為什麼。');
    if(!nhiReady) q.push('若要討論健保或自費，先確認是否還缺分期或生物標記。');
    else q.push('健保欄位適合用「條件對照」說明，不直接說成最終給付判定。');
    if(anat !== '—') q.push(`可用「第 ${anat} 期」搭配 receptor 狀態，簡短說明目前為什麼要討論這些項目。`);
    q.push('若病人關心費用，先分成健保、可能自費、需補資料三類，避免一次列出太多細節。');
    questions.innerHTML = q.map(x=>_journeyItem('•', _journeyEsc(x))).join('');
}
