document.addEventListener('DOMContentLoaded', ()=>{
    loadPatient();
});
let _calcInited=false;
function initCalcPage(){
    // Apply feature flag gating to each calculator sub-tab
    const tabFlagMap = {
        predict: 'predict',
        cts5: 'calc_cts5',
        pepi: 'calc_pepi',
        npi: 'calc_npi',
        magee: 'calc_magee',
        ihc4: 'calc_ihc4',
        hscore: 'calc_hscore',
        rcb: 'calc_rcb',
        gail: 'calc_gail',
        ln: 'calc_ln'
    };
    let firstVisibleTab = 'ext';
    Object.entries(tabFlagMap).forEach(([tab, flag]) => {
        const tabEl = document.querySelector(`[data-tab="${tab}"]`);
        const panelEl = document.getElementById('calcPanel-' + tab);
        const enabled = FEATURE_FLAGS[flag];
        if(tabEl) tabEl.style.display = enabled ? '' : 'none';
        if(panelEl) panelEl.style.display = enabled ? '' : 'none';
        if(enabled && firstVisibleTab === 'ext') firstVisibleTab = tab;
    });
    // If currently active tab was disabled, switch to first visible
    const activeTab = document.querySelector('#calcPage .calc-tab.active');
    if(activeTab && activeTab.style.display === 'none'){
        switchCalcTab(firstVisibleTab);
    } else {
        switchCalcTab(activeTab?.dataset.tab || firstVisibleTab);
    }
    // Run calculators only if enabled (avoid wasted DOM lookups for hidden ones)
    if(FEATURE_FLAGS.predict) calcPREDICT();
    if(FEATURE_FLAGS.calc_cts5) calcCTS5();
    if(FEATURE_FLAGS.calc_pepi) calcPEPI();
    if(FEATURE_FLAGS.calc_npi) calcNPI();
    if(FEATURE_FLAGS.calc_magee) calcMagee();
    if(FEATURE_FLAGS.calc_ihc4) calcIHC4();
    if(FEATURE_FLAGS.calc_hscore) calcHscore();
    if(FEATURE_FLAGS.calc_rcb) calcRCB();
    if(FEATURE_FLAGS.calc_gail) calcGail();
    if(FEATURE_FLAGS.calc_ln) calcLN();
}
function switchCalcTab(tab){
    document.querySelectorAll('#calcPage .calc-tab').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
    document.querySelectorAll('#calcPage .calc-panel').forEach(p=>p.classList.toggle('active', p.id==='calcPanel-'+tab));
    syncCalculatorFromWorkspace(tab);
}

function _setCalcVal(id, value){
    const el = document.getElementById(id);
    if(!el || value === undefined || value === null || value === '') return;
    const next = String(value);
    if(el.tagName === 'SELECT' && !Array.from(el.options).some(opt => opt.value === next)) return;
    el.value = next;
}

function syncCalculatorFromWorkspace(tab){
    if(typeof loadPatient === 'function') loadPatient();
    const p = _patient || {};
    const st = getWorkspaceStage(p);
    const erSign = _markerSign(p.er);
    const prSign = _markerSign(p.pr);
    const has = v => v !== undefined && v !== null && v !== '';
    const nodeCount = has(p.nodes_pos) ? +p.nodes_pos : (st.N && st.N !== 'N0' ? 1 : 0);
    const sizeMm = has(p.size) ? +p.size : null;
    const grade = has(p.grade) ? +p.grade : null;
    const her2Bin = p.her2 === '+' ? '1' : '0';
    const her2Cat = p.her2 === '+' ? '2' : (p.her2 === 'low' ? '1' : '0');
    const erH = erSign ? _markerHScore(p.er) : '';
    const prH = prSign ? _markerHScore(p.pr) : '';

    if(tab === 'predict'){
        _setCalcVal('pred_age', p.age);
        _setCalcVal('pred_mode', p.predict_mode || 'symp');
        _setCalcVal('pred_menopause', p.menopause);
        if(sizeMm) _setCalcVal('pred_size', sizeMm);
        if(has(p.nodes_pos)) _setCalcVal('pred_nodes', p.nodes_pos);
        if(grade) _setCalcVal('pred_grade', grade);
        if(erSign) _setCalcVal('pred_er', erSign === '+' ? 'pos' : 'neg');
        if(p.her2) _setCalcVal('pred_her2', p.her2 === '+' ? 'pos' : (p.her2 === '-' || p.her2 === 'low') ? 'neg' : 'unk');
        if(has(p.ki67)){
            const ki = +p.ki67;
            if(!isNaN(ki)) _setCalcVal('pred_ki67', ki >= 10 ? 'pos' : 'neg');
        }
        calcPREDICT();
    } else if(tab === 'cts5'){
        if(erSign) _setCalcVal('cts5_er', erSign === '+' ? 'pos' : 'neg');
        if(prSign) _setCalcVal('cts5_pr', prSign === '+' ? 'pos' : 'neg');
        if(p.her2) _setCalcVal('cts5_her2', p.her2 === '+' ? 'pos' : 'neg');
        if(has(p.nodes_pos)) _setCalcVal('cts5_n', p.nodes_pos);
        if(sizeMm) _setCalcVal('cts5_t', sizeMm);
        if(grade) _setCalcVal('cts5_g', grade);
        _setCalcVal('cts5_age', p.age);
        calcCTS5();
    } else if(tab === 'pepi'){
        if(sizeMm) _setCalcVal('pepi_t', (sizeMm > 50 || /^T[34]/.test(st.T || '')) ? '3' : '0');
        if(has(p.nodes_pos) || st.N) _setCalcVal('pepi_n', (nodeCount > 0 || (st.N && st.N !== 'N0')) ? '3' : '0');
        if(has(p.ki67)) _setCalcVal('pepi_ki67', p.ki67);
        if(erSign) _setCalcVal('pepi_er', erSign === '+' ? '0' : '3');
        calcPEPI();
    } else if(tab === 'npi'){
        if(sizeMm) _setCalcVal('npi_size', (sizeMm / 10).toFixed(1));
        if(has(p.nodes_pos) || st.N) _setCalcVal('npi_node', nodeCount === 0 ? '1' : (nodeCount <= 3 ? '2' : '3'));
        if(grade) _setCalcVal('npi_grade', grade);
        calcNPI();
    } else if(tab === 'magee'){
        if(grade) _setCalcVal('magee_ns', grade * 2 + 1);
        if(sizeMm) _setCalcVal('magee_size', sizeMm);
        if(erSign) _setCalcVal('magee_er', erH);
        if(prSign) _setCalcVal('magee_pr', prH);
        if(p.her2) _setCalcVal('magee_her2', her2Cat);
        if(has(p.ki67)) _setCalcVal('magee_ki67', p.ki67);
        calcMagee();
    } else if(tab === 'ihc4'){
        if(erSign) _setCalcVal('ihc4_er', erH);
        if(prSign) _setCalcVal('ihc4_pr', prH);
        if(p.her2) _setCalcVal('ihc4_her2', her2Bin);
        if(has(p.ki67)) _setCalcVal('ihc4_ki67', p.ki67);
        calcIHC4();
    } else if(tab === 'hscore'){
        _setCalcVal('hs_0', p.h_p0);
        _setCalcVal('hs_1', p.h_p1);
        _setCalcVal('hs_2', p.h_p2);
        _setCalcVal('hs_3', p.h_p3);
        calcHscore();
    } else if(tab === 'rcb'){
        _setCalcVal('rcb_d1', p.rcb_d1);
        _setCalcVal('rcb_d2', p.rcb_d2);
        _setCalcVal('rcb_finv', p.rcb_finv);
        _setCalcVal('rcb_ln', p.rcb_ln);
        _setCalcVal('rcb_dmet', p.rcb_dmet);
        calcRCB();
    } else if(tab === 'gail'){
        _setCalcVal('gail_age', p.age);
        _setCalcVal('gail_menarche', p.gail_menarche);
        _setCalcVal('gail_birth', p.gail_birth);
        _setCalcVal('gail_relatives', p.gail_relatives);
        _setCalcVal('gail_biopsy', p.gail_biopsy);
        _setCalcVal('gail_atypia', p.gail_atypia);
        _setCalcVal('gail_race', p.gail_race);
        calcGail();
    } else if(tab === 'ln'){
        if(sizeMm){
            _setCalcVal('ln_aln_size', (sizeMm / 10).toFixed(1));
            _setCalcVal('ln_nsln_size', (sizeMm / 10).toFixed(1));
            if(sizeMm <= 20) _setCalcVal('ln_l2_t', '1');
            else if(sizeMm <= 30) _setCalcVal('ln_l2_t', '2');
            else if(sizeMm <= 50) _setCalcVal('ln_l2_t', '3');
            else _setCalcVal('ln_l2_t', '4');
        }
        if(grade){
            _setCalcVal('ln_aln_grade', grade);
            _setCalcVal('ln_l2_grade', grade);
        }
        if(erSign) _setCalcVal('ln_aln_er', erSign === '+' ? '2' : '0');
        if(has(p.ki67)) _setCalcVal('ln_l2_ki', (+p.ki67 > 20) ? '1' : '0');
        if(has(p.nodes_pos)){
            _setCalcVal('ln_nsln_pos', Math.max(1, +p.nodes_pos || 1));
            _setCalcVal('ln_l2_pos', Math.max(1, +p.nodes_pos || 1));
        }
        calcLN();
    }
}
// ── CTS5 (Dowsett JCO 2018) ──
function calcCTS5(){
    const er = document.getElementById('cts5_er')?.value === 'pos' ? '+' : '-';
    const pr = document.getElementById('cts5_pr')?.value === 'pos' ? '+' : '-';
    const her2 = document.getElementById('cts5_her2')?.value === 'pos' ? '+' : '-';
    const N=+document.getElementById('cts5_n').value;
    const T=+document.getElementById('cts5_t').value;
    const G=+document.getElementById('cts5_g').value;
    const A=+document.getElementById('cts5_age').value;
    const exclusion = getCTS5Exclusion(er, pr, her2);
    if(exclusion){
        document.getElementById('cts5_result').innerHTML=`
          <div class="calc-result med">
            <div class="calc-result-label">CTS5 不適用</div>
            <div class="calc-result-main">${exclusion}</div>
            <div class="calc-result-detail">CTS5 應限用於 HR+（ER 或 PR 陽性）、HER2− 且完成 5 年內分泌治療後的病人。</div>
          </div>`;
        return;
    }
    if(isNaN(N)||isNaN(T)||isNaN(G)||isNaN(A)||T<=0||A<=0){
        document.getElementById('cts5_result').innerHTML='<div class="calc-result"><div class="calc-result-detail">請輸入完整資料。</div></div>';
        return;
    }
    // CTS5 = 0.438×N + 0.988×(0.093×T - 0.001×T²) + 0.375×G + 0.017×A
    const cts5 = 0.438*N + 0.988*(0.093*T - 0.001*T*T) + 0.375*G + 0.017*A;
    // 10-year DRR (years 5-10) per Dowsett 2018 derivation:
    // Years 5-10 DR risk = 1 - exp(-0.00223 * exp(CTS5))
    const drr10 = (1 - Math.exp(-0.00223 * Math.exp(cts5))) * 100;
    let cls='low', label='低風險', advice='不建議延長 endocrine therapy；標準 5 年即可。';
    if(cts5>=3.86){ cls='high'; label='高風險'; advice='強烈建議延長 endocrine therapy 至 10 年。'; }
    else if(cts5>=3.13){ cls='med'; label='中度風險'; advice='可考慮延長 endocrine therapy；個案討論利弊（骨密、心血管、子宮內膜）。'; }
    document.getElementById('cts5_result').innerHTML=`
      <div class="calc-result ${cls}">
        <div class="calc-result-label">CTS5 = ${cts5.toFixed(2)} · ${label}</div>
        <div class="calc-result-main">10 年遠端復發率 ≈ ${drr10.toFixed(1)}%</div>
        <div class="calc-result-detail">${advice}<br><span style="color:var(--text-muted);font-size:.78rem">分組：低 &lt;3.13；中 3.13–3.85；高 ≥3.86</span></div>
      </div>`;
}
// ── PEPI Score (Ellis JNCI 2008) ──
function calcPEPI(){
    const t=+document.getElementById('pepi_t').value;
    const n=+document.getElementById('pepi_n').value;
    const er=+document.getElementById('pepi_er').value;
    const ki=+document.getElementById('pepi_ki67').value;
    const r = calcPEPIPure(t, n, er, ki);
    if(!r) return;
    document.getElementById('pepi_result').innerHTML=`
      <div class="calc-result ${r.cls}">
        <div class="calc-result-label">PEPI Score = ${r.total} · ${r.label}</div>
        <div class="calc-result-main">5 年 RFS ${r.rfs}</div>
        <div class="calc-result-detail">${r.advice}<br><span style="color:var(--text-muted);font-size:.78rem">pT: ${r.parts.t} 分；pN: ${r.parts.n} 分；ER: ${r.parts.er} 分；Ki67 ${ki}%: ${r.parts.ki} 分</span></div>
      </div>`;
    document.querySelectorAll('#pepi_table tr[data-grp]').forEach(row=>row.classList.toggle('pepi-hl', +row.dataset.grp===r.grp));
}
// ── Magee Equations (Klein Mod Pathol 2013) ──
function calcMagee(){
    const ns=+document.getElementById('magee_ns').value;
    const size=+document.getElementById('magee_size').value;
    const er=+document.getElementById('magee_er').value;
    const pr=+document.getElementById('magee_pr').value;
    const her2cat=+document.getElementById('magee_her2').value;
    const ki67=+document.getElementById('magee_ki67').value;
    // HER2 status: 0=neg, 1=equivocal, 2=positive
    const her2 = her2cat===2 ? 1 : 0;
    // Magee Eq 1 (no Ki67): RS = 15.31385 + Nottingham*1.4055 + ER_H*(-0.01924) + PR_H*(-0.02925) + HER2*11.99435 + size*0.0986
    const m1 = 15.31385 + ns*1.4055 + er*(-0.01924) + pr*(-0.02925) + her2*11.99435 + size*0.0986;
    // Magee Eq 2 (with Ki67): RS = 18.8042 + Nottingham*2.34123 + ER_H*(-0.03749) + PR_H*(-0.03065) + HER2*11.8378 + size*0.13838 + Ki67*0.0035 (approx)
    const m2 = 18.8042 + ns*2.34123 + er*(-0.03749) + pr*(-0.03065) + her2*11.8378 + size*0.13838 + ki67*0.0035;
    // Magee Eq 3 (categorical, simplified): score derived from cat values
    const erCat = er>=200 ? 0 : (er>=10 ? 1 : 2);
    const prCat = pr>=200 ? 0 : (pr>=10 ? 1 : 2);
    const her2Cat = her2cat>=2 ? 4 : (her2cat===1 ? 1.5 : 0);
    const nsCat = ns<=5 ? 0 : (ns<=7 ? 1 : 2);
    const kiCat = ki67<10 ? 0 : (ki67<20 ? 1 : 2);
    const sizeCat = size<10 ? 0 : (size<20 ? 1 : (size<30 ? 2 : 3));
    const m3 = 13.424 + (erCat*1.4) + (prCat*1.6) + (her2Cat*5) + (nsCat*3) + (kiCat*1.6) + (sizeCat*0.5);
    const avg = (m1+m2+m3)/3;
    let cls='low', label='Low Risk', advice='等同 Oncotype RS &lt;18：endocrine alone 即可。';
    if(avg>=31){ cls='high'; label='High Risk'; advice='等同 Oncotype RS ≥31：建議 adjuvant chemo。'; }
    else if(avg>=18){ cls='med'; label='Intermediate Risk'; advice='等同 Oncotype RS 18–30：考慮 chemo 利弊（依年齡與 nodal status）。'; }
    document.getElementById('magee_result').innerHTML=`
      <div class="calc-result ${cls}">
        <div class="calc-result-label">Magee 平均估算 RS = ${avg.toFixed(1)} · ${label}</div>
        <div class="calc-result-main">${avg.toFixed(1)}</div>
        <div class="calc-result-detail">
          ${advice}<br>
          <span style="color:var(--text-muted);font-size:.78rem">Eq.1 (無 Ki67): ${m1.toFixed(1)} · Eq.2 (含 Ki67): ${m2.toFixed(1)} · Eq.3 (分類): ${m3.toFixed(1)}</span><br>
          <span style="color:var(--text-faint);font-size:.72rem">&#9432; 估算僅供參考，正式決策仍以實際 Oncotype DX RS 為準。</span>
        </div>
      </div>`;
}
// ── PREDICT v2.1/v2.3 (NHS Cambridge / Candido dos Reis BCR 2017) ──
// Coefficients verified against cran/nhs.predict R source code
// https://github.com/cran/nhs.predict/blob/master/R/predict.os.R
function _predictScreenVal(mode){
    if(mode === 'screen') return 1;
    if(mode === 'other')  return 0.204; // population proportion when unknown
    return 0; // 'symp' clinically detected
}
function _predictPI_ERpos(age, size, nodes, grade, mode, her2, ki67){
    // ER+ uses fractional polynomial transformations; grade is continuous
    const age_mfp1 = Math.pow(age/10, -2) - 0.0287449295;
    const age_mfp2 = Math.pow(age/10, -2) * Math.log(age/10) - 0.0510121013;
    const size_mfp = Math.log(Math.max(size,1)/100) + 1.545233938;
    const nodes_mfp = Math.log((nodes+1)/10) + 1.387566896;
    const screen = _predictScreenVal(mode);
    const her2_beta = (her2==='pos') ? 0.2413 : (her2==='neg' ? -0.0762 : 0);
    const ki67_beta = (ki67==='pos') ? 0.14904 : (ki67==='neg' ? -0.11333 : 0);
    return 34.53642  * age_mfp1
         + -34.20342 * age_mfp2
         + 0.7530729 * size_mfp
         + 0.7060723 * nodes_mfp
         + 0.746655  * grade            // continuous (1, 2, 3)
         + -0.22763366 * screen
         + her2_beta
         + ki67_beta;
}
function _predictPI_ERneg(age, size, nodes, grade, mode, her2){
    // ER- uses different functional forms; grade is binary (G2/G3 vs G1)
    const age_mfp = age - 56.3254902;
    const size_mfp = Math.pow(Math.max(size,1)/100, 0.5) - 0.5090456276;
    const nodes_mfp = Math.log((nodes+1)/10) + 1.086916249;
    const grade_val = (grade === 2 || grade === 3) ? 1 : 0;
    const her2_beta = (her2==='pos') ? 0.2413 : (her2==='neg' ? -0.0762 : 0);
    return 0.0089827 * age_mfp
         + 2.093446  * size_mfp
         + 0.6260541 * nodes_mfp
         + 1.129091  * grade_val
         + her2_beta;     // screen has no effect for ER-; ki67 ignored for ER-
}
// Other-cause mortality prognostic index (depends on age only)
function _predictMI(age){
    return 0.0698252 * (Math.pow(age/10, 2) - 34.23391957);
}
// Cumulative baseline hazards (NOT log-baseline) for years 1..15
function _predictBaseCumBC(t, isERpos){
    if(isERpos){
        // ER+ smoothed baseline: exp(0.7424 - 7.528/sqrt(t) - 1.813*ln(t)/sqrt(t))
        return Math.exp(0.7424402 - 7.527762 / Math.sqrt(t) - 1.812513 * Math.log(t) / Math.sqrt(t));
    } else {
        // ER- smoothed baseline: exp(-1.156 + 0.471/t² - 3.514/t)
        return Math.exp(-1.156036 + 0.4707332 / (t * t) - 3.51355 / t);
    }
}
function _predictBaseCumOC(t){
    return Math.exp(-6.052919 + 1.079863 * Math.log(t) + 0.3255321 * Math.sqrt(t));
}
function calcPREDICT(){
    const el = document.getElementById('pred_result');
    if(!el) return;
    const age = +document.getElementById('pred_age').value;
    const mode = document.getElementById('pred_mode').value;
    const menopause = document.getElementById('pred_menopause')?.value || '';
    const size = +document.getElementById('pred_size').value;
    const nodes = +document.getElementById('pred_nodes').value;
    const grade = +document.getElementById('pred_grade').value;
    const er = document.getElementById('pred_er').value;
    const her2 = document.getElementById('pred_her2').value;
    const ki67 = document.getElementById('pred_ki67').value;
    const endo = +document.getElementById('pred_endo').value;
    const chemo = +document.getElementById('pred_chemo').value;
    const trast = +document.getElementById('pred_trast').value;
    const bis = +document.getElementById('pred_bis').value;
    const useBis = bis === 1 && menopause === 'post';

    if(!age || !size || isNaN(nodes) || isNaN(grade) || age<25 || age>85 || size<1){
        el.innerHTML = '<div class="calc-result"><div class="calc-result-detail">請填入合法的年齡 (25–85)、腫瘤大小、Grade、淋巴結數。</div></div>';
        return;
    }

    const isERpos = er === 'pos';
    const pi = isERpos
        ? _predictPI_ERpos(age, size, nodes, grade, mode, her2, ki67)
        : _predictPI_ERneg(age, size, nodes, grade, mode, her2);
    const mi = _predictMI(age);

    // Build treatment list with NHS v2.1 published log HRs
    // NOTE: v2.1 model only specifies chemo gen 2 and gen 3; no separate CMF coefficient
    const txList = [];
    if(isERpos && endo >= 5){
        txList.push({name: endo===10?'內分泌治療 10 年':'內分泌治療 5 年', logHR: -0.3857, color:'#0369a1'});
    }
    if(chemo > 0){
        // NHS v2.1 only defines gen 2 (-0.248) and gen 3 (-0.446); CMF treated as gen 2
        const chemoLogHR = chemo===2 ? -0.248 : (chemo===3 ? -0.446 : 0);
        const chemoNames = {2:'化療 第 2 代 (anthracycline / CMF)', 3:'化療 第 3 代 (anth + taxane)'};
        if(chemoLogHR !== 0) txList.push({name: chemoNames[chemo], logHR: chemoLogHR, color:'#7c3aed'});
    }
    if(her2 === 'pos' && trast === 1){
        txList.push({name:'Trastuzumab', logHR: -0.3567, color:'#16a34a'});
    }
    if(useBis){
        txList.push({name:'Bisphosphonates', logHR: -0.198, color:'#ea580c'});
    }

    // Compute survival using NHS competing-risks framework (replicates predict.os.R)
    // Annual hazards from cumulative baselines, multiplied by exp(pi+tx_logHR), then re-cumulated.
    const years = [5, 10, 15];
    function computeSurv(txLogHRSum){
        // Pre-compute cumulative baselines for all 15 years
        const cumBC0 = [], cumOC0 = [];
        for(let t=1; t<=15; t++){
            cumBC0.push(_predictBaseCumBC(t, isERpos));
            cumOC0.push(_predictBaseCumOC(t));
        }
        // Annual baselines
        const annBC0 = cumBC0.map((v,i)=> i===0 ? v : v - cumBC0[i-1]);
        const annOC0 = cumOC0.map((v,i)=> i===0 ? v : v - cumOC0[i-1]);
        // Apply HRs to get annual treated hazards
        const annBC = annBC0.map(v => v * Math.exp(pi + txLogHRSum));
        const annOC = annOC0.map(v => v * Math.exp(mi));
        // Cumulate
        const cumBC = []; let acc=0;
        annBC.forEach(v => { acc += v; cumBC.push(acc); });
        const cumOC = []; acc=0;
        annOC.forEach(v => { acc += v; cumOC.push(acc); });
        // Survival
        const sBC = cumBC.map(c => Math.exp(-c));
        const sOC = cumOC.map(c => Math.exp(-c));
        const sAll = sBC.map((b,i) => b * sOC[i]);
        return { sAll, sBC, sOC };
    }

    // Build stages: baseline + each treatment cumulative
    const stages = [{name:'無輔助治療（baseline）', cumLogHR:0, isBaseline:true}];
    let cumLogHR = 0;
    for(const tx of txList){
        cumLogHR += tx.logHR;
        stages.push({name: tx.name, cumLogHR: cumLogHR, color: tx.color, isBaseline:false});
    }

    const stagesData = stages.map(s => {
        const sv = computeSurv(s.cumLogHR);
        return {
            ...s,
            survByYear: years.map(y => sv.sAll[y-1])
        };
    });

    // Render table
    let html = '<div style="margin-top:.85rem;overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:.85rem;min-width:480px">';
    html += '<thead><tr><th style="text-align:left;padding:.5rem .6rem;border-bottom:2px solid var(--border);background:#f8fafc">階段</th>';
    years.forEach(y => { html += `<th style="text-align:center;padding:.5rem .6rem;border-bottom:2px solid var(--border);background:#f8fafc">${y} 年存活率</th>`; });
    html += '</tr></thead><tbody>';
    stagesData.forEach((s, i) => {
        const isLast = i === stagesData.length - 1 && stagesData.length > 1;
        const rowStyle = (i===0?'border-bottom:1px solid var(--border);':'') + (isLast?'font-weight:700;background:#fefce8;':'');
        html += `<tr style="${rowStyle}">`;
        const colorBar = s.color ? `<span style="display:inline-block;width:3px;height:14px;background:${s.color};margin-right:.4rem;vertical-align:middle;border-radius:2px"></span>` : '';
        html += `<td style="padding:.42rem .6rem">${colorBar}${s.name}</td>`;
        s.survByYear.forEach((sv, j) => {
            const pct = (sv*100).toFixed(1);
            let delta = '';
            if(i > 0){
                const prev = stagesData[i-1].survByYear[j];
                const d = (sv - prev) * 100;
                if(d > 0.05) delta = ` <span style="color:#16a34a;font-size:.78rem;font-weight:600">+${d.toFixed(1)}</span>`;
            }
            html += `<td style="padding:.42rem .6rem;text-align:center">${pct}%${delta}</td>`;
        });
        html += '</tr>';
    });
    html += '</tbody></table></div>';

    // Summary box (only if treatments selected)
    if(txList.length > 0){
        const totalSurv = stagesData[stagesData.length-1].survByYear;
        const baseSurv = stagesData[0].survByYear;
        html += `<div class="calc-result med" style="margin-top:.7rem">
            <div class="calc-result-label">綜合所有治療下的整體存活率</div>
            <div style="font-size:1.05rem;font-weight:700;color:#854d0e;margin-top:.2rem">
                5 年: ${(totalSurv[0]*100).toFixed(1)}% <span style="color:#166534;font-size:.85rem">(+${((totalSurv[0]-baseSurv[0])*100).toFixed(1)})</span>
                · 10 年: ${(totalSurv[1]*100).toFixed(1)}% <span style="color:#166534;font-size:.85rem">(+${((totalSurv[1]-baseSurv[1])*100).toFixed(1)})</span>
                · 15 年: ${(totalSurv[2]*100).toFixed(1)}% <span style="color:#166534;font-size:.85rem">(+${((totalSurv[2]-baseSurv[2])*100).toFixed(1)})</span>
            </div>
            <div class="calc-result-detail" style="margin-top:.3rem">
                <span style="color:var(--text-muted);font-size:.78rem">PI = ${pi.toFixed(3)} · 治療數 = ${txList.length}</span>
            </div>
        </div>`;
    } else {
        const baseSurv = stagesData[0].survByYear;
        html += `<div class="calc-result" style="margin-top:.7rem">
            <div class="calc-result-label">無治療下的存活率</div>
            <div style="font-size:1.05rem;font-weight:700;color:#0e7490;margin-top:.2rem">
                5 年 ${(baseSurv[0]*100).toFixed(1)}% · 10 年 ${(baseSurv[1]*100).toFixed(1)}% · 15 年 ${(baseSurv[2]*100).toFixed(1)}%
            </div>
            <div class="calc-result-detail">請於上方選擇輔助治療以查看獲益。</div>
        </div>`;
    }
    if(bis === 1 && menopause !== 'post'){
        html += '<div class="calc-result-detail" style="margin-top:.45rem;color:#92400e">Bisphosphonates 在 PREDICT v2.3 僅套用停經後變數；目前停經狀態不是「已停經」，本次未計入。</div>';
    }
    el.innerHTML = html;
}
function loadPredictFromWorkspace(){
    if(typeof _patient === 'undefined' || !_patient.age){
        alert('Workspace 尚未填入資料。請先到「病人 Workspace」分頁填入年齡、腫瘤大小等基本資訊。');
        return;
    }
    const p = _patient;
    const setVal = (id, v) => { const e=document.getElementById(id); if(e && v!=null && v!=='') e.value = v; };
    setVal('pred_age', p.age);
    setVal('pred_menopause', p.menopause);
    setVal('pred_size', p.size);
    setVal('pred_nodes', p.nodes_pos);
    if(p.grade) setVal('pred_grade', p.grade);
    if(p.er) setVal('pred_er', p.er === '+' ? 'pos' : 'neg');
    if(p.her2){
        const v = p.her2==='+' ? 'pos' : (p.her2==='-'||p.her2==='low') ? 'neg' : 'unk';
        setVal('pred_her2', v);
    }
    if(p.ki67){
        const ki = +p.ki67;
        if(!isNaN(ki) && ki > 0) setVal('pred_ki67', ki >= 10 ? 'pos' : 'neg');
    }
    calcPREDICT();
}

// ── NPI (Galea 1992) ──
function calcNPI(){
    const el = document.getElementById('npi_result');
    if(!el) return;
    const size = +document.getElementById('npi_size').value;
    const node = +document.getElementById('npi_node').value;
    const grade = +document.getElementById('npi_grade').value;
    if(!size||!node||!grade){ el.innerHTML=''; return; }
    const npi = 0.2*size + node + grade;
    let group, surv5, cls;
    if(npi <= 2.4){ group='Excellent'; surv5='~95%'; cls='low'; }
    else if(npi <= 3.4){ group='Good'; surv5='~85%'; cls='low'; }
    else if(npi <= 4.4){ group='Moderate I'; surv5='~70%'; cls='med'; }
    else if(npi <= 5.4){ group='Moderate II'; surv5='~55%'; cls='med'; }
    else if(npi <= 6.4){ group='Poor'; surv5='~50%'; cls='high'; }
    else { group='Very Poor'; surv5='~30%'; cls='high'; }
    el.innerHTML=`<div class="calc-result ${cls}">
        <div class="calc-result-label">NPI = ${npi.toFixed(2)} · ${group}</div>
        <div class="calc-result-main">5 年存活率 ${surv5}</div>
        <div class="calc-result-detail">0.2 × ${size}cm + ${node} (淋巴) + ${grade} (Grade) = ${npi.toFixed(2)}</div>
    </div>`;
}
// ── IHC4 (Cuzick JCO 2011) ──
function calcIHC4(){
    const el = document.getElementById('ihc4_result');
    if(!el) return;
    const erH = +document.getElementById('ihc4_er').value;
    const prH = +document.getElementById('ihc4_pr').value;
    const her2 = +document.getElementById('ihc4_her2').value;
    const ki67 = +document.getElementById('ihc4_ki67').value;
    if(isNaN(erH)||isNaN(prH)||isNaN(her2)||isNaN(ki67)){ el.innerHTML=''; return; }
    const er10 = erH/30;
    const pr10 = prH/30;
    const ki67d = ki67/100;
    const ihc4 = 94.7 * (-0.100*er10 - 0.079*pr10 + 0.586*her2 + 0.240*Math.log(1 + 10*ki67d));
    // NOTE: cutoffs below are APPROXIMATE; Cuzick 2011 used cohort-specific tertiles
    let group, cls, advice;
    if(ihc4 < -25){ group='相對低 (近似)'; cls='low'; advice='與低 Oncotype RS 相關性較強'; }
    else if(ihc4 < 0){ group='較低 (近似)'; cls='low'; advice='連續分數較低，輔助臨床綜合判斷'; }
    else if(ihc4 < 25){ group='中等 (近似)'; cls='med'; advice='中等分數，建議綜合年齡/分期判斷'; }
    else { group='相對高 (近似)'; cls='high'; advice='與高 Oncotype RS 相關性較強'; }
    el.innerHTML=`<div class="calc-result ${cls}">
        <div class="calc-result-label">IHC4 連續分數 = ${ihc4.toFixed(2)} · ${group}</div>
        <div class="calc-result-main">${ihc4.toFixed(1)}</div>
        <div class="calc-result-detail">${advice}<br>
            <span style="color:var(--text-muted);font-size:.78rem">ER10=${er10.toFixed(2)} · PR10=${pr10.toFixed(2)} · HER2=${her2} · Ki67=${ki67}%</span><br>
            <span style="color:#b45309;font-size:.74rem">⚠️ 上述 cutoffs 為近似分隔，非 Cuzick 原文之 tertile。應以連續分數搭配臨床整體判斷，非絕對風險分類。</span>
        </div>
    </div>`;
}
// ── H-score ──
function calcHscore(){
    const el = document.getElementById('hs_result');
    if(!el) return;
    const p0 = +document.getElementById('hs_0').value;
    const p1 = +document.getElementById('hs_1').value;
    const p2 = +document.getElementById('hs_2').value;
    const p3 = +document.getElementById('hs_3').value;
    const r = calcHscorePure(p0, p1, p2, p3);
    if(!r) return;
    let warn = '';
    if(Math.abs(r.total - 100) > 0.5) warn = `<br><span style="color:#b45309;font-size:.78rem">⚠️ 各強度合計 ${r.total}%（應為 100%）</span>`;
    el.innerHTML=`<div class="calc-result ${r.cls}">
        <div class="calc-result-label">H-score · ${r.group}</div>
        <div class="calc-result-main">${r.h}</div>
        <div class="calc-result-detail">1×${p1}% + 2×${p2}% + 3×${p3}% = ${r.h}${warn}</div>
    </div>`;
}
// ── RCB (Symmans JCO 2007) ──
function calcRCB(){
    const el = document.getElementById('rcb_result');
    if(!el) return;
    const d1 = +document.getElementById('rcb_d1').value;
    const d2 = +document.getElementById('rcb_d2').value;
    const finv = +document.getElementById('rcb_finv').value;
    const ln = +document.getElementById('rcb_ln').value;
    const dmet = +document.getElementById('rcb_dmet').value;
    const r = calcRCBPure(d1, d2, finv, ln, dmet);
    if(!r) return;
    el.innerHTML=`<div class="calc-result ${r.cls}">
        <div class="calc-result-label">${r.klass}</div>
        <div class="calc-result-main">${r.rcb.toFixed(2)}</div>
        <div class="calc-result-detail">${r.surv}<br>
            <span style="color:var(--text-muted);font-size:.78rem">d_prim=${r.dprim.toFixed(1)}mm · 原發成份 ${r.primComp.toFixed(2)} · 淋巴成份 ${r.nodalComp.toFixed(2)}</span>
        </div>
    </div>`;
}
// ── Gail Model (BCRAT v2 simplified) ──
function calcGail(){
    const el = document.getElementById('gail_result');
    if(!el) return;
    const age = +document.getElementById('gail_age').value;
    const rrMen = +document.getElementById('gail_menarche').value;
    const rrBirth = +document.getElementById('gail_birth').value;
    const rrRel = +document.getElementById('gail_relatives').value;
    const biopsy = +document.getElementById('gail_biopsy').value;
    const atypia = +document.getElementById('gail_atypia').value;
    const race = document.getElementById('gail_race').value;
    if(!age || age < 35 || age > 85){ el.innerHTML='<div class="calc-result"><div class="calc-result-detail">年齡需介於 35–85 歲。</div></div>'; return; }
    const r = calcGailPure(age, rrMen, rrBirth, rrRel, biopsy, atypia, race);
    if(!r) return;
    el.innerHTML=`<div class="calc-result ${r.cls}">
        <div class="calc-result-label">Gail Model 5 年風險（簡化估算）</div>
        <div class="calc-result-main">${r.risk5y.toFixed(2)}%</div>
        <div class="calc-result-detail">
            <strong>終身風險（粗估）</strong>：${r.lifetimeRisk.toFixed(1)}%<br>
            <strong>建議</strong>：${r.advice}<br>
            <span style="color:var(--text-muted);font-size:.78rem">RR 總和 = ${r.totalRR.toFixed(2)} (initial=${rrMen}×birth=${rrBirth}×rel=${rrRel}×biopsy=${r.rrBio.toFixed(2)}) · 種族 = ${r.raceFactor}</span><br>
            <span style="color:var(--text-faint);font-size:.72rem">⚠️ 此為簡化估算。臨床決策請至 <a href="https://bcrisktool.cancer.gov/" target="_blank">NCI 官方 BCRAT</a>。</span>
        </div>
    </div>`;
}

// ── LN Prediction Nomograms ──
function calcLN(){
    const alnEl = document.getElementById('ln_aln_result');
    if(!alnEl) return;

    const aln = calcQiuAlnPure(
        +document.getElementById('ln_aln_td').value,
        +document.getElementById('ln_aln_cortex').value,
        +document.getElementById('ln_aln_hilum').value,
        +document.getElementById('ln_aln_grade').value,
        +document.getElementById('ln_aln_size').value,
        +document.getElementById('ln_aln_er').value
    );
    if(aln){
        alnEl.innerHTML=`<div class="calc-result ${aln.cls}">
            <div class="calc-result-label">Positive axillary US 後 ALN metastasis</div>
            <div class="calc-result-main">${aln.risk.toFixed(1)}%</div>
            <div class="calc-result-detail">logit = ${aln.logit.toFixed(3)}。Qiu 2016 validation：13.8% cutoff 的 FNR 約 5.3%；結果僅供模型參考。</div>
        </div>`;
    }

    const nslnEl = document.getElementById('ln_nsln_result');
    const nsln = calcNonSlnPure(
        +document.getElementById('ln_nsln_size').value,
        +document.getElementById('ln_nsln_multi').value,
        +document.getElementById('ln_nsln_lvi').value,
        +document.getElementById('ln_nsln_pos').value,
        +document.getElementById('ln_nsln_neg').value
    );
    if(nslnEl && nsln){
        nslnEl.innerHTML=`<div class="calc-result ${nsln.cls}">
            <div class="calc-result-label">SLN+ 後 non-SLN metastasis</div>
            <div class="calc-result-main">${nsln.risk.toFixed(1)}%</div>
            <div class="calc-result-detail">logit = ${nsln.logit.toFixed(3)}。此為公開 logistic equation，不是 MSK 官方 Non-SLN nomogram 係數。</div>
        </div>`;
    }

    const l2El = document.getElementById('ln_l2_result');
    const l2 = calcLevel2AlnPure(
        +document.getElementById('ln_l2_pos').value,
        +document.getElementById('ln_l2_t').value,
        +document.getElementById('ln_l2_ki').value,
        +document.getElementById('ln_l2_grade').value
    );
    if(l2El && l2){
        l2El.innerHTML=`<div class="calc-result ${l2.cls}">
            <div class="calc-result-label">Level II ALN metastasis</div>
            <div class="calc-result-main">${l2.risk.toFixed(1)}%</div>
            <div class="calc-result-detail">logit = ${l2.logit.toFixed(3)}。Jiang 2017 validation AUC 0.816；低於 10% 時原研究 FNR 約 7.41%。</div>
        </div>`;
    }
}

