const FEATURE_FLAGS_DEFAULT = {
    // Stable features (production-ready)
    breast: true,
    inpatient: true,
    icd: true,
    surgery: true,
    trials: true,
    ajcc: true,
    calculator: true,
    workspace: true,
    darkMode: true,
    patientJourney: false,    // Removed from public/dev entry points
    // Calculator sub-features (stable: well-validated formulas)
    calc_cts5: true,        // Dowsett 2018, well-validated
    calc_pepi: true,        // Ellis 2008, well-validated
    calc_npi: true,         // Galea 1992, well-validated
    calc_magee: true,       // Klein 2013, multiple equations
    calc_hscore: true,      // pure math, no clinical interpretation
    calc_rcb: true,         // Symmans 2007, well-validated formula
    calc_ln: true,          // LN prediction models with published equations
    // Validated features (passed R nhs.predict 2595-case validation)
    predict: true,           // ✅ Validated: 100% pass vs R, max err 0.02%
    // Beta features (experimental, may not be fully validated)
    ajccPrognostic: true,    // AJCC v8 prognostic staging support; verify against official tables
    nhiReverseLookup: false, // Moved out of staging workspace; drug module owns NHI lookup
    calc_ihc4: true,         // Formula is available; card must always open a real calculator
    calc_gail: true          // Standalone general-population breast cancer risk entry
};
// PREDICT removed from BETA_KEYS after R validation passed (commit v1.8)
const FEATURE_FLAGS_BETA_KEYS = ['ajccPrognostic'];
const FEATURE_FLAGS_KEY = '_feature_flags';
let FEATURE_FLAGS = { ...FEATURE_FLAGS_DEFAULT };
function loadFeatureFlags(){
    try {
        const saved = localStorage.getItem(FEATURE_FLAGS_KEY);
        if(saved) FEATURE_FLAGS = { ...FEATURE_FLAGS_DEFAULT, ...JSON.parse(saved) };
        delete FEATURE_FLAGS.nccn;
        FEATURE_FLAGS.calc_ihc4 = true;
        FEATURE_FLAGS.calc_gail = true;
    } catch(e){ console.warn('Failed to load feature flags', e); }
    // URL override: ?dev=1 enables all
    try {
        const params = new URLSearchParams(window.location.search);
        if(params.get('dev')==='1'){
            Object.keys(FEATURE_FLAGS).forEach(k => FEATURE_FLAGS[k] = true);
        }
        if(params.get('stable')==='1'){
            FEATURE_FLAGS_BETA_KEYS.forEach(k => FEATURE_FLAGS[k] = false);
        }
    } catch(e){}
    FEATURE_FLAGS.patientJourney = false;
    delete FEATURE_FLAGS.nccn;
}
function saveFeatureFlags(){
    try { localStorage.setItem(FEATURE_FLAGS_KEY, JSON.stringify(FEATURE_FLAGS)); } catch(e){}
}
function setFlag(name, value){
    if(name === 'calc_ihc4' || name === 'calc_gail') value = true;
    FEATURE_FLAGS[name] = !!value;
    saveFeatureFlags();
    if(typeof loadLanding === 'function') loadLanding();
}
function setDevMode(enableAll){
    if(enableAll){
        Object.keys(FEATURE_FLAGS_DEFAULT).forEach(k => FEATURE_FLAGS[k] = true);
    } else {
        Object.keys(FEATURE_FLAGS_DEFAULT).forEach(k => {
            FEATURE_FLAGS[k] = !FEATURE_FLAGS_BETA_KEYS.includes(k);
        });
    }
    FEATURE_FLAGS.calc_ihc4 = true;
    FEATURE_FLAGS.calc_gail = true;
    FEATURE_FLAGS.patientJourney = false;
    delete FEATURE_FLAGS.nccn;
    saveFeatureFlags();
    renderSettings();
    if(typeof loadLanding === 'function') loadLanding();
}
function resetFeatureFlags(){
    if(!confirm('重置為預設值（所有功能開啟）？')) return;
    FEATURE_FLAGS = { ...FEATURE_FLAGS_DEFAULT };
    localStorage.removeItem(FEATURE_FLAGS_KEY);
    renderSettings();
    if(typeof loadLanding === 'function') loadLanding();
}
