function autoSelectCT(cmStr){
  const cm = parseFloat(cmStr);
  const label = document.getElementById('tumorSizeLabel');
  if(isNaN(cm) || cm < 0){ if(label) label.textContent = 'cm → 對應 T 分期'; return; }
  const mm = cm * 10;
  let tVal = '';
  if(mm <= 0) tVal = '';
  else if(mm <= 1) tVal = 'T1mi';
  else if(mm <= 5) tVal = 'T1a';
  else if(mm <= 10) tVal = 'T1b';
  else if(mm <= 20) tVal = 'T1c';
  else if(mm <= 50) tVal = 'T2';
  else tVal = 'T3';
  const sel = document.getElementById('ajccT');
  if(sel) sel.value = tVal;
  if(label) label.textContent = tVal ? ('= ' + tVal + '（' + cm + ' cm）') : 'cm → 對應 T 分期';
  calcAJCC();
}

function toggleNAC(){
  const isNAC = document.getElementById('nacReceived')?.checked;
  const titleEl = document.getElementById('pTNMPanelTitle');
  const pTLabel = document.getElementById('pTLabel');
  if(titleEl) titleEl.innerHTML = isNAC ? '術前化療後病理期別 <span>ypTNM</span>' : '病理期別 <span>pTNM</span>';
  if(pTLabel) pTLabel.textContent = isNAC ? 'ypT — 殘餘腫瘤' : 'pT — 腫瘤大小/範圍';
  const pTSel = document.getElementById('ajccPT');
  if(pTSel){
    pTSel.querySelectorAll('.nac-opt').forEach(o => o.remove());
    if(isNAC){
      const opts = [
        {v:'ypT0', t:'ypT0 — 無殘留浸潤癌（pCR）'},
        {v:'ypTis', t:'ypTis — 僅剩 DCIS（pCR 乳腺）'}
      ];
      opts.reverse().forEach(o => {
        const el = document.createElement('option');
        el.value = o.v; el.textContent = o.t; el.className = 'nac-opt';
        pTSel.insertBefore(el, pTSel.options[1]);
      });
    }
  }
  calcAJCC();
}

